package com.rulecraft.decisionops.decisionapi.api;import com.rulecraft.decisionops.decisionapi.DecisionApiEvaluationService;import com.rulecraft.decisionops.decisionapi.DecisionApiEvaluationService.*;import com.rulecraft.decisionops.decisionapi.security.DecisionApiPrincipal;import com.rulecraft.decisionops.explainability.ExplainabilityService;import com.rulecraft.decisionops.explainability.ExplainabilityService.TraceDetail;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.util.UUID;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @SecurityRequirement(name="decisionApiKey") @RequestMapping("/api/runtime/v1/decisions/{serviceKey}") public class DecisionRuntimeApiController {private final DecisionApiEvaluationService service;private final ExplainabilityService explainability;public DecisionRuntimeApiController(DecisionApiEvaluationService service,ExplainabilityService explainability){this.service=service;this.explainability=explainability;}@PostMapping("/evaluate")SingleResponse evaluate(@PathVariable String serviceKey,@RequestBody SingleCommand body,Authentication auth){return service.single(principal(auth),serviceKey,body);}@PostMapping("/batch")BatchResponse batch(@PathVariable String serviceKey,@RequestBody BatchCommand body,Authentication auth){return service.batch(principal(auth),serviceKey,body);}@GetMapping("/traces/{evaluationId}")TraceDetail trace(@PathVariable String serviceKey,@PathVariable UUID evaluationId,Authentication auth){return explainability.publicDetail(principal(auth),serviceKey,evaluationId);}private DecisionApiPrincipal principal(Authentication auth){return (DecisionApiPrincipal)auth.getPrincipal();}}
